#[derive(Clone, Copy, Debug)]
pub struct DurableTaskGuestClient<'a, H: lenso_guest_sdk::HostImports> {
    capability: lenso_guest_sdk::GuestCapability<'a, H>,
}

impl<'a, H: lenso_guest_sdk::HostImports> DurableTaskGuestClient<'a, H> {
    pub fn from_context(context: &'a lenso_guest_sdk::GuestContext<H>) -> Result<Self, lenso_guest_sdk::GuestError<serde_json::Value>> {
        context
            .require(CAPABILITY_ID, DESCRIPTOR_VERSION, &[CANCEL_OPERATION, OBSERVE_OPERATION, RECOVER_OPERATION, SIGNAL_OPERATION, START_OPERATION], &[WAIT_OPERATION], &[])
            .map(|capability| Self { capability })
    }

    pub fn cancel(&self, request: &CancelRequest) -> Result<CancelResponse, lenso_guest_sdk::GuestError<CancelError>> {
        self.capability.request(CANCEL_OPERATION, request)
    }

    pub fn observe(&self, request: &ObserveRequest) -> Result<ObserveResponse, lenso_guest_sdk::GuestError<ObserveError>> {
        self.capability.request(OBSERVE_OPERATION, request)
    }

    pub fn recover(&self, request: &RecoverRequest) -> Result<RecoverResponse, lenso_guest_sdk::GuestError<RecoverError>> {
        self.capability.request(RECOVER_OPERATION, request)
    }

    pub fn signal(&self, request: &SignalRequest) -> Result<SignalResponse, lenso_guest_sdk::GuestError<SignalError>> {
        self.capability.request(SIGNAL_OPERATION, request)
    }

    pub fn start(&self, request: &StartRequest) -> Result<StartResponse, lenso_guest_sdk::GuestError<StartError>> {
        self.capability.request(START_OPERATION, request)
    }

    pub fn wait(&self, request: &WaitOpen) -> Result<lenso_guest_sdk::GuestStream<H, TaskUpdate, WaitError>, lenso_guest_sdk::GuestError<WaitError>> {
        self.capability.open_stream(WAIT_OPERATION, request)
    }
}

#[derive(Debug, Default)]
pub struct DurableTaskJsonCodec;

impl lenso_runtime_codec::JsonCapabilityCodec for DurableTaskJsonCodec {
    fn capability_id(&self) -> &'static str { CAPABILITY_ID }

    fn descriptor_version(&self) -> &'static str { DESCRIPTOR_VERSION }

    fn descriptor_digest(&self) -> &'static str { DESCRIPTOR_DIGEST }

    fn request_operations(&self) -> &'static [&'static str] { &[CANCEL_OPERATION, OBSERVE_OPERATION, RECOVER_OPERATION, SIGNAL_OPERATION, START_OPERATION] }
    fn stream_operations(&self) -> &'static [&'static str] { &[WAIT_OPERATION] }
    fn event_operations(&self) -> &'static [&'static str] { &[] }

    fn encode_request(&self, operation: &str, request: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        match operation {
            CANCEL_OPERATION => {
                let value = request.downcast_ref::<CancelRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            OBSERVE_OPERATION => {
                let value = request.downcast_ref::<ObserveRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            RECOVER_OPERATION => {
                let value = request.downcast_ref::<RecoverRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            SIGNAL_OPERATION => {
                let value = request.downcast_ref::<SignalRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            START_OPERATION => {
                let value = request.downcast_ref::<StartRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn decode_response(&self, operation: &str, value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        match operation {
            CANCEL_OPERATION => serde_json::from_value::<CancelResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            OBSERVE_OPERATION => serde_json::from_value::<ObserveResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            RECOVER_OPERATION => serde_json::from_value::<RecoverResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            SIGNAL_OPERATION => serde_json::from_value::<SignalResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            START_OPERATION => serde_json::from_value::<StartResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn decode_domain_error(&self, operation: &str, value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        match operation {
            CANCEL_OPERATION => serde_json::from_value::<CancelError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            OBSERVE_OPERATION => serde_json::from_value::<ObserveError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            RECOVER_OPERATION => serde_json::from_value::<RecoverError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            SIGNAL_OPERATION => serde_json::from_value::<SignalError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            START_OPERATION => serde_json::from_value::<StartError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn encode_stream_open(&self, operation: &str, request: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        match operation {
            WAIT_OPERATION => {
                let value = request.downcast_ref::<WaitOpen>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn encode_stream_message(&self, operation: &str, message: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        match operation {
            WAIT_OPERATION => {
                let value = message.downcast_ref::<TaskUpdate>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn decode_stream_message(&self, operation: &str, value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        match operation {
            WAIT_OPERATION => serde_json::from_value::<TaskUpdate>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn decode_stream_domain_error(&self, operation: &str, value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        match operation {
            WAIT_OPERATION => serde_json::from_value::<WaitError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn encode_event(&self, operation: &str, _event: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        Err(runtime_codec_unknown_operation(operation))
    }

    fn invoke_host_request(&self, dependency: lenso_kernel::PluginDependencyHandle, operation: String, request: serde_json::Value, context: InvocationContext) -> lenso_runtime_codec::JsonHostRequestFuture {
        match operation.as_str() {
            CANCEL_OPERATION => {
                let request = serde_json::from_value::<CancelRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<DurableTaskCancel>()?;
                    match handle.invoke_with_context(CANCEL_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            OBSERVE_OPERATION => {
                let request = serde_json::from_value::<ObserveRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<DurableTaskObserve>()?;
                    match handle.invoke_with_context(OBSERVE_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            RECOVER_OPERATION => {
                let request = serde_json::from_value::<RecoverRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<DurableTaskRecover>()?;
                    match handle.invoke_with_context(RECOVER_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            SIGNAL_OPERATION => {
                let request = serde_json::from_value::<SignalRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<DurableTaskSignal>()?;
                    match handle.invoke_with_context(SIGNAL_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            START_OPERATION => {
                let request = serde_json::from_value::<StartRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<DurableTaskStart>()?;
                    match handle.invoke_with_context(START_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            _ => Box::pin(std::future::ready(Err(runtime_codec_unknown_operation(&operation)))),
        }
    }

    fn open_host_stream(&self, dependency: lenso_kernel::PluginStreamDependencyHandle, operation: String, request: serde_json::Value, context: InvocationContext) -> lenso_runtime_codec::JsonHostStreamOpenFuture {
        match operation.as_str() {
            WAIT_OPERATION => {
                let request = serde_json::from_value::<WaitOpen>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<DurableTaskWait>()?;
                    match handle.open_with_context(WAIT_OPERATION, context, request).await? {
                        Ok(stream) => Ok(Ok(lenso_runtime_codec::json_host_stream::<DurableTaskWait>(
                            stream,
                            |value| serde_json::from_value::<TaskUpdate>(value).map_err(|_| runtime_codec_protocol_failure()),
                            |message| serde_json::to_value(message).map_err(|_| runtime_codec_protocol_failure()),
                            |error| serde_json::to_value(error).map_err(|_| runtime_codec_protocol_failure()),
                        ))),
                        Err(error) => serde_json::to_value(error)
                            .map(Err)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            _ => Box::pin(std::future::ready(Err(runtime_codec_unknown_operation(&operation)))),
        }
    }

    fn publish_host_event(&self, _dependency: lenso_kernel::PluginEventDependencyHandle, operation: String, _event: serde_json::Value, _context: InvocationContext) -> futures::future::LocalBoxFuture<'static, Result<(), RuntimeFailure>> {
        Box::pin(std::future::ready(Err(runtime_codec_unknown_operation(&operation))))
    }
}

fn runtime_codec_protocol_failure() -> RuntimeFailure { RuntimeFailure::ProtocolViolation { capability: CAPABILITY_ID } }

fn runtime_codec_unknown_operation(operation: &str) -> RuntimeFailure {
    RuntimeFailure::UnknownOperation { capability: CAPABILITY_ID, operation: operation.to_owned() }
}
